UPDATE payment_order
SET status_code = #{to},
    updated_at = CAST(SYSTIMESTAMP AT TIME ZONE 'Asia/Seoul' AS TIMESTAMP)
WHERE company_id = #{companyId}
  AND payment_order_id = #{orderId}
  AND status_code = #{from}

UPDATE payment_order
SET status_code = 'ORD_CONFIRMED',
    updated_at = CAST(SYSTIMESTAMP AT TIME ZONE 'Asia/Seoul' AS TIMESTAMP)
WHERE company_id = #{companyId}
  AND payment_order_id = #{orderId}
  AND status_code IN ('ORD_CREATED', 'ORD_FAILED')

